def maxSubArray(nums):
    cur = best = nums[0]           # NOT 0 - all-negative arrays
    for x in nums[1:]:
        cur = max(x, cur + x)      # extend, or start fresh at x
        best = max(best, cur)
    return best

# with indices, for the follow-up
def maxSubArrayIdx(nums):
    cur = best = nums[0]
    s = bs = be = 0
    for i in range(1, len(nums)):
        if cur + nums[i] < nums[i]:
            cur, s = nums[i], i     # dropping the old sum, restart here
        else:
            cur += nums[i]
        if cur > best:
            best, bs, be = cur, s, i
    return best, bs, be
```
